'use strict';

const path = require('path');
const filePaths = process.argv.splice(2);
const CLIEngine = require('eslint').CLIEngine;

const cli = new CLIEngine({
    useEslintrc: false,
    baseConfig: {
        settings: {
            extjs: {
                toolkit: 'modern',
                fromVersion: '7.0',
                toVersion: '7.9'
            }
        },
        rules: {
            'no-existing-alias-override': 'error',
            'no-existing-class-override': 'warn',
            'no-existing-method-override': 'warn',
            'override-method-call': 'warn',

            'no-deprecated-class-usage': 'warn',
            'no-deprecated-config-usage': 'warn',
            'no-deprecated-method-call': 'warn',
            'no-deprecated-method-override': 'warn',
            'no-deprecated-property-usage': 'warn',

            'no-private-class-usage': 'warn',
            'no-private-config-usage': 'warn',
            'no-private-method-call': 'warn',
            'no-private-method-override': 'warn',
            'no-private-property-usage': 'warn',

            'no-removed-class-usage': 'error',
            'no-removed-config-usage': 'error',
            'no-removed-method-call': 'error',
            'no-removed-method-override': 'error',
            'no-removed-property-usage': 'error'
        }
    },
    ignorePath: path.resolve(__dirname, '../.eslintignore-empty'),
    ignorePattern: [
        '**/ext',
        '**/sass/example',
        '**/build',
        '**/.sencha',
        '**/packages/remote',
        '**/node_modules',
        '**/*min.js',
        '**/bootstrap.js',
        '**/classic.js',
        '**/modern.js',
        '**/generatedFiles/*.js'
    ],
    rulePaths: [path.resolve(__dirname, 'rules')]
});

// run eslint with our custom rules against the desired files
const report = cli.executeOnFiles(filePaths);

// get the default formatter
const formatter = cli.getFormatter();

// Also could do...
// var formatter = cli.getFormatter("compact");
// var formatter = cli.getFormatter("./my/formatter.js");

// output to console
console.log(formatter(report.results));
